<script setup lang="ts">
import { Plus, Trash2 } from 'lucide-vue-next'
type Block={type:string;level?:2|3;text?:string;ordered?:boolean;items?:string[];src?:string;alt?:string;caption?:string;fileId?:string};const props=defineProps<{modelValue:Block[];folder?:string}>();const emit=defineEmits<{ 'update:modelValue':[Block[]] }>();function update(next:Block[]){emit('update:modelValue',next)}function add(type:string){const next=[...props.modelValue];next.push(type==='heading'?{type,level:2,text:''}:type==='list'?{type,ordered:false,items:['']}:type==='image'?{type,src:'',alt:'',caption:''}:{type,text:''});update(next)}function remove(i:number){const next=[...props.modelValue];next.splice(i,1);update(next)}function set(i:number,value:Block){const next=[...props.modelValue];next[i]=value;update(next)}
</script><template><div class="space-y-3"><div class="flex items-center justify-between gap-2"><h4 class="text-sm font-semibold">Body Blocks</h4><select class="min-h-[36px] rounded-full border px-3 text-xs" @change="(e)=>{const x=e.target as HTMLSelectElement;if(x.value)add(x.value);x.value=''}"><option value="">Tambah block...</option><option value="paragraph">Paragraph</option><option value="heading">H2 / H3</option><option value="image">Image</option><option value="blockquote">Quote</option><option value="list">Bullet / Numbered List</option><option value="callout">Info / Callout</option></select></div><div v-for="(block,i) in modelValue" :key="i" class="rounded-xl border border-neutral-line p-3"><div class="flex items-center justify-between"><span class="text-xs font-semibold uppercase text-gold">{{block.type}}</span><button type="button" class="text-red-700" title="Hapus block" aria-label="Hapus block" @click="remove(i)"><Trash2 class="h-4 w-4"/></button></div><textarea v-if="['paragraph','blockquote','callout'].includes(block.type)" :value="block.text" rows="3" class="mt-2 w-full rounded-lg border px-3 py-2 text-sm" @input="set(i,{...block,text:($event.target as HTMLTextAreaElement).value})"/><div v-else-if="block.type==='heading'" class="mt-2 grid gap-2 sm:grid-cols-[80px_1fr]"><select :value="block.level" class="rounded-lg border px-2" @change="set(i,{...block,level:Number(($event.target as HTMLSelectElement).value) as 2|3})"><option :value="2">H2</option><option :value="3">H3</option></select><input :value="block.text" class="rounded-lg border px-3" @input="set(i,{...block,text:($event.target as HTMLInputElement).value})"/></div><div v-else-if="block.type==='list'"><select :value="String(block.ordered)" class="mt-2 rounded-lg border px-2 text-xs" @change="set(i,{...block,ordered:($event.target as HTMLSelectElement).value==='true'})"><option value="false">Bullet</option><option value="true">Numbered</option></select><textarea :value="(block.items||[]).join('\n')" rows="3" class="mt-2 w-full rounded-lg border px-3 py-2 text-sm" @input="set(i,{...block,items:($event.target as HTMLTextAreaElement).value.split('\n')})"/></div><div v-else-if="block.type==='image'" class="mt-2 space-y-2"><MediaImageUploader v-model="block.src" :folder="folder||'articles'" label="Image" @update:file-id="set(i,{...block,fileId:$event})"/><input :value="block.alt" placeholder="Alt text" class="w-full rounded-lg border px-3 py-2 text-sm" @input="set(i,{...block,alt:($event.target as HTMLInputElement).value})"/><input :value="block.caption" placeholder="Caption" class="w-full rounded-lg border px-3 py-2 text-sm" @input="set(i,{...block,caption:($event.target as HTMLInputElement).value})"/></div></div><button type="button" class="inline-flex items-center gap-1 rounded-full border px-3 py-1.5 text-xs" @click="add('paragraph')"><Plus class="h-4 w-4"/>Tambah paragraph</button></div></template>
